/* Shared media-aware include/exclude facets. Counts describe loaded records, not the entire catalog. */
(function(root){
 const norm=s=>{const v=String(s||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/_/g,' ').replace(/\s+/g,' ').trim();return ({'sci-fi':'science fiction','sci fi':'science fiction','scifi':'science fiction','science-fiction':'science fiction','hip hop':'hip-hop','hip-hop/rap':'hip-hop','r & b':'r&b','ps5':'playstation 5','ps4':'playstation 4','pc (microsoft windows)':'pc','single player':'single-player'})[v]||v;};
 const demographic=s=>({'shonen':'Shounen','shounen':'Shounen','shōnen':'Shounen','seinen':'Seinen','shojo':'Shoujo','shoujo':'Shoujo','josei':'Josei','kids':'Kids','kodomo':'Kids'}[norm(s)]||'');
 function values(m,field){
  const genres=m.genres||[],tags=m.content_tags||[];
  if(field==='demographic')return ['manga','anime'].includes(m.kind)?[...new Set([...genres,...tags].map(demographic).filter(Boolean))]:[];
  if(field==='genres')return [...new Set(genres.filter(x=>!demographic(x)).flatMap(x=>/^action & adventure$/i.test(x)?['Action','Adventure']:/^sci-fi & fantasy$/i.test(x)?['Science fiction','Fantasy']:[x]).map(norm))];
  if(field==='tags')return tags.filter(x=>!demographic(x)).map(norm);
  if(field==='platforms')return ['game','visual_novel'].includes(m.kind)?(m.platforms||[]).map(norm):[];
  return m.format?[norm(m.format)]:[];
 }
 const fields=['genres','tags','demographic','platforms','format'];
 function matches(m,state={}){const included=[],excluded=[];for(const field of fields){const set=new Set(values(m,field).map(norm));for(const [value,mode] of Object.entries(state[field]||{})){if(mode===1)included.push(set.has(norm(value)));if(mode===-1)excluded.push(set.has(norm(value)));}}return !excluded.some(Boolean)&&(!included.length||(state.mode==='any'?included.some(Boolean):included.every(Boolean)));}
 function options(records,field,state={}){const out=new Map();for(const m of records)for(const value of values(m,field)){const key=norm(value);out.set(key,{value:key,label:field==='demographic'?demographic(value):value,count:(out.get(key)?.count||0)+1});}for(const value of Object.keys(state[field]||{}))if(!out.has(norm(value)))out.set(norm(value),{value:norm(value),label:field==='demographic'?demographic(value):value,count:0});return [...out.values()].map(o=>{const next={...state,[field]:{...(state[field]||{})}};delete next[field][o.value];return {...o,count:records.filter(m=>matches(m,next)&&values(m,field).map(norm).includes(o.value)).length};}).sort((a,b)=>a.label.localeCompare(b.label));}
 const api={values,matches,options,demographic};if(typeof module==='object')module.exports=api;if(typeof document==='undefined')return;
 const states=new Map(),panels=new Map();
 try{for(const [k,v] of Object.entries(JSON.parse(sessionStorage.getItem('folio-facets-v1')||'{}')))states.set(k,v);}catch{}
 const kindFor=context=>context==='search'?(document.querySelector('#live-kind').value||FolioSearch.intent(liveQuery).kind):type==='All media'?'':type==='Music'?'music':Object.entries(mediaTypes).find(([,label])=>label===type)?.[0]||'custom:'+type;
 const stateFor=context=>{const key=context+':'+kindFor(context);if(!states.has(key))states.set(key,{mode:'all'});return states.get(key);};
 const count=state=>fields.reduce((n,f)=>n+Object.keys(state[f]||{}).length,0);
 function save(){try{sessionStorage.setItem('folio-facets-v1',JSON.stringify(Object.fromEntries(states)));}catch{}}
 function changed(context){save();if(context==='search')drawResults();else render();panels.get(context)?.dispatchEvent(new Event('change',{bubbles:true}));}
 function mount(context){if(panels.has(context))return panels.get(context);const panel=document.createElement('details');panel.className='adaptive-facets';panel.innerHTML='<summary></summary><div class="adaptive-facet-body"></div>';const target=context==='search'?document.querySelector('#live-filters'):document.querySelector('.facet-filters');target.append(panel);panels.set(context,panel);panel.addEventListener('click',e=>{const button=e.target.closest('[data-facet]');if(!button)return;const state=stateFor(context),field=button.dataset.facet,value=button.dataset.value;state[field]||={};const old=state[field][value]||0,next=old===0?1:old===1?-1:0;if(next)state[field][value]=next;else delete state[field][value];changed(context);panel.querySelector(`[data-facet="${field}"][data-value="${CSS.escape(value)}"]`)?.focus();});panel.addEventListener('change',e=>{if(e.target.matches('.facet-mode')){stateFor(context).mode=e.target.value;changed(context);}});panel.addEventListener('click',e=>{if(e.target.closest('.facet-clear')){states.set(context+':'+kindFor(context),{mode:'all'});changed(context);}});return panel;}
 function paint(context,records){const panel=mount(context),state=stateFor(context),kind=kindFor(context),groups=fields.map(field=>[field,options(records,field,state)]).filter(([,rows])=>rows.length);const active=count(state);panel.querySelector('summary').textContent=`Tags & features${active?' · '+active+' active':''}`;const label={genres:'Genres',tags:kind==='book'?'Subjects':'Themes & tags',demographic:'Demographic',platforms:'Platforms',format:'Format'};
  const search=panel.querySelector('.facet-find')?.value||'',focused=panel.querySelector('.facet-find')===document.activeElement;
  panel.querySelector('.adaptive-facet-body').innerHTML=`<div class="facet-topline"><p>Click a tag: <b>+ include</b> → <b>− exclude</b> → neutral. Filters adapt to ${esc(mediaTypes[kind]||'each media type')}.</p><button type="button" class="facet-clear" ${active?'':'disabled'}>Clear tags</button></div><div class="facet-options"><label>Include matches<select class="facet-mode"><option value="all" ${state.mode==='all'?'selected':''}>All selected tags</option><option value="any" ${state.mode==='any'?'selected':''}>Any selected tag</option></select></label><label>Find a tag<input type="search" class="facet-find" value="${esc(search)}" placeholder="Filter available tags…"></label></div>${groups.map(([field,rows])=>`<fieldset><legend>${label[field]}</legend><div class="facet-chips">${rows.map(o=>{const value=state[field]?.[o.value]||0;return `<button type="button" data-facet="${field}" data-value="${esc(o.value)}" data-state="${value}" aria-pressed="${value===-1?'mixed':String(!!value)}" aria-label="${value===1?'Included':value===-1?'Excluded':'Neutral'}: ${esc(FolioMetadataDisplay.label(o.label))}" title="${value===0?'Include':value===1?'Exclude':'Clear'} ${esc(FolioMetadataDisplay.label(o.label))}"><span aria-hidden="true">${value===1?'+':value===-1?'−':'○'}</span> ${esc(FolioMetadataDisplay.label(o.label))}<small>${o.count}</small></button>`;}).join('')}</div></fieldset>`).join('')||'<p>No tags supplied for these loaded titles.</p>'}<p class="facet-note">${context==='search'?'Applies to loaded results; Load more to widen the selection. Missing tags cannot be inferred.':'Applies to your library. Tag choices are separate for each media type.'}</p>`;
  const input=panel.querySelector('.facet-find');input.oninput=()=>{const q=norm(input.value);panel.querySelectorAll('[data-facet]').forEach(b=>b.hidden=!b.dataset.value.includes(q));};input.oninput();if(focused){input.focus();input.setSelectionRange(search.length,search.length);}
 }
 api.filterSearch=rows=>{const kind=kindFor('search'),base=FolioIdentity.group([...liveRecords,...(root.FolioCreatorSearch?.related()||[]),...(root.FolioAssociations?.related()||[])]).filter(m=>!kind||FolioIdentity.matchesKind(m,kind));paint('search',base);return rows.filter(m=>matches(m,stateFor('search')));};
 const media=x=>x.metadata||{kind:Object.entries(mediaTypes).find(([,label])=>label===x.type)?.[0]||'',genres:genresOf(x),content_tags:tagsOf(x),platforms:[]};
 api.filterLibrary=rows=>{const base=items.filter(x=>type==='All media'||x.type===type).map(media);paint('library',base);return rows.filter(x=>matches(media(x),stateFor('library')));};
 api.count=context=>count(stateFor(context));api.active=()=>count(stateFor('search'))>0;api.clearSearch=()=>{states.set('search:'+kindFor('search'),{mode:'all'});save();};
 api.restoreLegacy=values=>{for(const [id,context,field] of [['live-genre','search','genres'],['live-platform','search','platforms'],['genre-filter','library','genres']]){const value=values?.[id];if(value&&value!=='all'){const state=stateFor(context),target=field==='genres'&&demographic(value)?'demographic':field;state[target]||={};state[target][norm(value)]=1;}}save();};
 root.FolioFacets=api;
 for(const id of ['live-genre','live-platform','genre-filter']){const select=document.getElementById(id);select.value=id==='genre-filter'?'all':'';select.closest('label')?.classList.add('legacy-facet');select.classList.add('legacy-facet');}
 document.querySelector('#live-reset').addEventListener('click',()=>{api.clearSearch();drawResults();});
 document.querySelector('#reset-filters').addEventListener('click',()=>{states.set('library:'+kindFor('library'),{mode:'all'});save();render();});
 drawResults();render();
})(globalThis);
